def _chain_policies(self, wallet_id: str) -> dict[str, dict]:
    """从 chain_policy 事件序列恢复各资产的链确认策略（每资产取最后一条）。

    策略只由审计事件持久化（事件之外不写任何状态文件）；畸形事件
    fail-closed（RecoveryError），绝不静默按缺省处理。纯只读，
    不分配 seq。"""
    policies: dict[str, dict] = {}
    for event in self._audit.events_by_type(
        wallet_id, audit.TYPE_CHAIN_POLICY
    ):
        asset_id, policy = self._chain_policy_shape(wallet_id, event)
        policies[asset_id] = policy
    return policies

def _chain_reports(self, wallet_id: str) -> dict[str, dict]:
    """从 chain_report 事件序列恢复各操作的最后一条报告。

    报告状态只由审计事件持久化；畸形事件 fail-closed
    （RecoveryError）。纯只读，不分配 seq。"""
    reports: dict[str, dict] = {}
    for event in self._audit.events_by_type(
        wallet_id, audit.TYPE_CHAIN_REPORT
    ):
        operation_id, report = self._chain_report_shape(wallet_id, event)
        reports[operation_id] = report
    return reports

@staticmethod
def _report_transition_error(
    policy: dict, last: dict | None, report: dict
) -> str | None:
    """新报告相对上一条报告的状态机校验；合法返回 None，否则返回错误信息。

    首报绑定 tx_id 与 chain_id：后续报告换 tx/换链一律冲突；同块
    （高度与哈希均同）确认数只增不减，且低于门槛的同体重放不应产生
    事件（对账时据此识别篡改）；换块的高度回退不得超过策略
    reorg_window，换块后确认数可降。"""
    if last is None:
        return None
    if report["tx_id"] != last["tx_id"]:
        return "tx_id conflicts with the reported transaction"
    if report["chain_id"] != last["chain_id"]:
        return "chain_id conflicts with the reported chain"
    same_block = (
        report["block_height"] == last["block_height"]
        and report["block_hash"] == last["block_hash"]
    )
    if same_block:
        if report["confirmations"] < last["confirmations"]:
            return "confirmations must not decrease on the same block"
        if (
            report == last
            and report["confirmations"] < policy["required_confirmations"]
        ):
            # 低于门槛的同体重放在线只回 200 不记事件：日志里出现
            # 这样的重复报告事件即矛盾现场（达门槛的重复报告是崩溃
            # 重试补齐提交的合法残留，不在此列）
            return "duplicate report below the required confirmations"
        return None
    if (
        last["block_height"] - report["block_height"]
        > policy["reorg_window"]
    ):
        return "block height regression exceeds the reorg window"
    return None

def put_chain_policy(
    self,
    wallet_id: str,
    asset_id: object,
    chain_id: object,
    enabled: object,
    required_confirmations: object,
    reorg_window: object,
) -> dict:
    """设置（或覆盖）某资产的跨链确认策略。成功 200 返回 Q。

#: 在归一化前就须按落盘规范序严格核对**外层七字段**键序的事件类型集合。
#: 读取不重排外层键序，故落盘原序在加载时即可核对：错序即不可对账现场
#: （RecoveryError），且 _read_strict 是追加写盘前的唯一加载路径，错序
#: 现场绝不写盘。
_STRICT_OUTER_ORDER_TYPES = frozenset(
    (
        TYPE_DKG_FAILOVER,
    )
)


def _stored_details_has_canonical_order(event: dict) -> bool:
    """判定一条落盘事件的 details 是否恰为 README 既定键序（归一化之前）。

    仅用于 :data:`_STRICT_DETAILS_ORDER_TYPES` 中的类型。对带多种精确
    键集的类型，details 键集须恰等于其中某一种既定键序；否则即视为错序。
    """
    order = _DETAILS_KEY_ORDER.get(event.get("type"))
    details = event.get("details")
    if order is None or not isinstance(details, dict):
        return True
    if order and isinstance(order[0], tuple):
        return any(
            list(details) == list(candidate)
            for candidate in order
            if set(details) == set(candidate)
        )
    return list(details) == list(order)


def _order_event_details(event: dict) -> None:
    """把既定事件类型的 details 就地重排为 README 既定键序。

    仅当 details 键集与既定键序恰好一致时重排；键集不符的现场留给各
    语义对账路径 fail-closed，绝不在这里猜写。chain_vote 事件按精确
    键集在策略序 {sources,quorum} 与票序 {source,report,state} 间选择
    （两种语义共用同一事件类型）。
    """
    order = _DETAILS_KEY_ORDER.get(event.get("type"))
    details = event.get("details")
    if order is None or not isinstance(details, dict):
        return
    if order and isinstance(order[0], tuple):
        matched = next(
            (candidate for candidate in order if set(details) == set(candidate)),
            None,
        )
        if matched is None:
            return
        event["details"] = {key: details[key] for key in matched}
        return
    if set(details) != set(order):
        return
    event["details"] = {key: details[key] for key in order}


def _canonicalize_sorted(value: object) -> object:
    """递归重排为 sort_keys 规范序（与 WalletStore._atomic_write 同字节）。"""
    if isinstance(value, dict):
        return {k: _canonicalize_sorted(value[k]) for k in sorted(value)}
    if isinstance(value, list):
        return [_canonicalize_sorted(item) for item in value]
    return value


def _canonical_event(event: object) -> object:
    """单条事件的落盘规范形：七字段 sort_keys，惟既定类型 details 保序。"""
    if not isinstance(event, dict):
        return _canonicalize_sorted(event)
    canonical = {}
    for key in sorted(event):
        value = event[key]
        if (
            key == "details"
            and event.get("type") in _DETAILS_KEY_ORDER
            and isinstance(value, dict)
        ):
            # 保留构造/读取时已归一为 README 既定顺序的 details 键序
            canonical[key] = value
        else:
            canonical[key] = _canonicalize_sorted(value)
    return canonical


def _canonical_log(data: dict) -> dict:
    """审计日志整体落盘规范形（顶层与各事件 sort_keys，既定 details 保序）。"""
    canonical = {}
    for key in sorted(data):
        value = data[key]
        if key == "events" and isinstance(value, list):
            canonical[key] = [_canonical_event(event) for event in value]
        else:
            canonical[key] = _canonicalize_sorted(value)
    return canonical


def _atomic_write_log(path: str, data: dict) -> None:
    """与 WalletStore._atomic_write 相同的临时文件 + 原子替换；序列化按
    _canonical_log（既定事件类型的 details 按 README 既定键序落盘）。"""
    directory = os.path.dirname(path)
    os.makedirs(directory, exist_ok=True)
    fd, tmp_path = tempfile.mkstemp(dir=directory, prefix=".tmp-", suffix=".json")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            json.dump(_canonical_log(data), f, ensure_ascii=False, indent=2)
            f.write("\n")
        os.replace(tmp_path, path)
    except BaseException:
        try:
            os.unlink(tmp_path)
        except FileNotFoundError:
            pass
        raise


